local UIModule = CS.Engine.UI.UIModule
local ActivityCrisisContractTaskDialog = Class("ActivityCrisisContractTaskDialog")
---@type ActivityCrisisUtils
local ActivityCrisisUtils = import('Game.Activity.CrisisContract.ActivityCrisisUtils')
local Cell = "CellNode"
local CellPath = "Game.Activity.CrisisContract.Cell.ActivityCrisisContractTaskCell"
function ActivityCrisisContractTaskDialog:__init()
    self.selectType = ActivityCrisisUtils.TaskType.Normal
    self.selectIndex = 1
end

function ActivityCrisisContractTaskDialog:__delete()
    self.selectType = nil
    self.selectIndex = nil
    self.controller = nil
end

function ActivityCrisisContractTaskDialog:Awake()
    self.parameters = self.controller.Argument.parameters
    if not isNull(self.parameters.questId) then
        self.selectQuestId = self.parameters.questId
        local levelVo = ActivityCrisisUtils.GetCrisisEventLevelVo(self.selectQuestId)
        self.selectType = levelVo.type
    end
    self:InitNodeEnv()
end

function ActivityCrisisContractTaskDialog:InitNodeEnv()
    self.taskTypeTabEnv_ = CfUtils.GetLuaScr(self.CommonTabToggleLeftExpand, "Game.Behaviours.CommonTabToggleLeftExpand")
end

function ActivityCrisisContractTaskDialog:OnFocus(focus)

end

function ActivityCrisisContractTaskDialog:OnShow()

end

function ActivityCrisisContractTaskDialog:OnInitialize()
    local activityData = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityData()
    self.activityData = activityData
    GameUtils.Request(Interfaces.ActivityStrangeTaleTask,{activityUuid = self.activityData.id },function(request,response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            ActivityCrisisUtils.GetActivityCrisisMgr():InitialDojo(data)
            self:InitLeftTab()
        end
    end)
end

function ActivityCrisisContractTaskDialog:InitLeftTab()
    local TabDataConfig = {
        {  name = localize("常驻关卡"),
           taskType    = ActivityCrisisUtils.TaskType.Normal,
           func        = Bind(self, self.OnClickTabHandler_),
           redPointFun = Bind(self,self.OnRefreshTabRedPoint)
        },
        {  name = localize("轮替关卡"),
           taskType    = ActivityCrisisUtils.TaskType.Rotation,
           func        = Bind(self, self.OnClickTabHandler_),
           redPointFun = Bind(self,self.OnRefreshTabRedPoint)
        },
    }

    self.TabChildConfig = {
        [ActivityCrisisUtils.TaskType.Normal] = self:GetTabChildConfigData(ActivityCrisisUtils.TaskType.Normal),
        [ActivityCrisisUtils.TaskType.Rotation] = self:GetTabChildConfigData(ActivityCrisisUtils.TaskType.Rotation),
    }

    if isNotNull(self.selectQuestId) then
        for i, v in pairs(self.TabChildConfig[self.selectType]) do
            if v.data.questId == self.selectQuestId then
                self.selectIndex = i
                break
            end
        end
    end

    self.taskTypeTabEnv_:Refresh(TabDataConfig, self.TabChildConfig, self.selectType, self.selectIndex)
    self.taskTypeTabEnv_:MovePanelToIndex(self.selectIndex)
end

function ActivityCrisisContractTaskDialog:OnRefreshTabRedPoint(data)
    local dojo =  ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityDojo()
    local tasks = dojo:GetTasks()
    local taskData
    local type = data.taskType
    if type == ActivityCrisisUtils.TaskType.Rotation then
        taskData = tasks.rotation
    else
        taskData = tasks.permanent
    end

    for k, v in pairs(taskData) do
        for i, j in pairs(v.task) do
            if j.status == 1 then
                return true
            end
        end
    end

    return false
end

function ActivityCrisisContractTaskDialog:GetTabChildConfigData(type)
    local dojo =  ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityDojo()
    local tasks = dojo:GetTasks()
    local data = {}

    local taskData
    if type == ActivityCrisisUtils.TaskType.Rotation then
        taskData = tasks.rotation
    else
        taskData = tasks.permanent
    end

    for i, v in pairs(taskData) do
        local questVo = ActivityCrisisUtils.GetCrisisEventLevelVo(v.questId)
        table.insert(data,{name = questVo.name, redPoint = v.taskTips, data = v,lock = self:GetIsLock(v),lockToast = localize("事件开启时间未到"), redPointFun = function() return self:GetRedPoint(v)  end,countDownData = self:GetCountDownTimeData(v),func = Bind(self,self.OnClickChildTabHandler_) })
    end

    return data
end

function ActivityCrisisContractTaskDialog:GetRedPoint(data)
    for i, v in pairs(data.task) do
        if v.status == 1 then
            return true
        end
    end

    return false
end

function ActivityCrisisContractTaskDialog:GetIsLock(data)
    if checkNumber(data.unlockCountdown) > 0  and  checkNumber(data.unlockCountdown) - os.time() > 0 then
        return true
    end
    return false
end

function ActivityCrisisContractTaskDialog:GetCountDownTimeData(data)
    local isLock = self:GetIsLock(data)
    if isLock then
        return nil
    end

    local remainTime = checkNumber(data.limitCountdown) - os.time()
    if checkNumber(data.limitCountdown) > 0  and  remainTime > 0 then
        return { isNormalTime = true , remainTime = remainTime }
    end
    return nil
end

function ActivityCrisisContractTaskDialog:OnClickTabHandler_(tabData)
    self.taskType = tabData.taskType
end

function ActivityCrisisContractTaskDialog:OnClickChildTabHandler_(data)
    self.questId = data.data.questId
    self.questData = data.data.task
    self:RefreshListView()
end

function ActivityCrisisContractTaskDialog:RefreshListView()
    table.sort(self.questData,function(a,b)
        local aIsGet = a.status == 2 and 1 or 0
        local bIsGet = b.status == 2 and 1 or 0
        if aIsGet == bIsGet then
            local aCanGet = a.status == 1 and 1 or 0
            local bCanGet = b.status == 1 and 1 or 0
            if aCanGet == bCanGet then
                return a.id < b.id
            else
                return aCanGet > bCanGet
            end
        else
            return aIsGet < bIsGet
        end
    end)
    if self.ListView then
        if not self.ListView.IsListViewInit then
            self.ListView:InitListView(#self.questData, Bind(self, self.OnRefreshCellIndex))
        else
            GameUtils.ReloadData(self.ListView, #self.questData)
        end
    end
end


function ActivityCrisisContractTaskDialog:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.questData then
        return
    end

    local cell = listView:NewListViewItem(Cell)
    if not isNull(cell) then
        local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
        if not isNull(tableCellEnv) then
            tableCellEnv:SetCallBack(Bind(self,self.OnDrawTaskReward))
            tableCellEnv:Refresh(self.questData[index + 1])
        end
    end
    return cell
end

function ActivityCrisisContractTaskDialog:OnDrawTaskReward(taskData)
    GameUtils.Request(Interfaces.ActivityStrangeTaleReceiveTaskRewards,{activityUuid = self.activityData.id,questId = self.questId,taskId = taskData.id},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            taskData.status = 2
            ActivityCrisisUtils.GetActivityCrisisMgr():UpdateReceiveIds(taskData.id)
            if table.count(data.rewards) > 0 then
                GoodsUtils.DrawRewards(data.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards }})
            end
            self.taskTypeTabEnv_:RedPointRefresh()
            self:RefreshListView()
        end
    end)
end

function ActivityCrisisContractTaskDialog:OnFinalize()

end

return ActivityCrisisContractTaskDialog